import {api} from '../api.js';
import {state, selectedTenant} from '../state.js';
import {$, $$, acronym, applyFieldErrors, badge, bindBreadcrumbs, breadcrumb, dateFmt, empty, esc, loading, modal, money, number, pageHead, pct, readonlyBanner, setActiveNav, statusTone, toast} from '../ui.js';
import {cumulativeAdminApplies, renderCumulativeAdmin} from './cumulative_admin.js';
import {openThemeManager, themeSummaryCard} from './theme_manager.js';

export async function renderAdminPage(route, ctx) {
  setActiveNav(route);
  const page = $('#page');
  page.innerHTML = loading();
  try {
    if (cumulativeAdminApplies(route)) return await renderCumulativeAdmin(route,page,ctx);
    if (route === 'portfolio') return await portfolio(page, ctx);
    if (route === 'client-success') return await clientSuccess(page, ctx);
    if (route === 'pricing') return await pricing(page, ctx);
    if (route === 'partner-economics') return await partnerEconomics(page, ctx);
    if (route === 'onboarding') return await onboarding(page, ctx);
    if (route === 'service-requests') return await serviceRequests(page, ctx);
    if (route === 'training') return await trainingAdmin(page);
    if (route === 'support-access') return await supportAccess(page);
    if (route === 'system') return await systemHealth(page);
    if (route === 'client-360') return await client360(page, ctx);
    return await portfolio(page, ctx);
  } catch (error) {
    page.innerHTML = empty('Unable to load this workspace', error.message);
    toast(error.message, 'error');
  }
}

async function portfolio(page, ctx) {
  const data = await api('/api/portfolio/summary');
  const k = data.kpis;
  page.innerHTML = `${pageHead('Portfolio Command Center','Run the RMR software business, manage clients, and act on adoption or expansion signals.',`<button class="button secondary" data-route="service-requests">Service requests</button><button class="button" id="add-client">+ Add New Client</button>`)}
  <section class="hero-card"><div><div class="eyebrow">RMR SOFTWARE BUSINESS</div><h2>See the health, value, and economics of the entire customer portfolio.</h2><p>Client business records remain separate and client-controlled.</p></div><div class="hero-stat"><span>${acronym('ARR')}</span><strong>${money(k.arr_cents)}</strong><small>Annual recurring revenue</small></div></section>
  <div class="kpi-grid">${actionKpi('Active clients',number(k.active_clients),'Live and private tenants','active')}${actionKpi(acronym('MRR'),money(k.mrr_cents),'Contracted monthly revenue','mrr')}${actionKpi('Recognized revenue',money(k.recognized_revenue_cents),'Current billing period','recognized')}${actionKpi('RMR share',money(k.rmr_share_cents),'Current transaction rules','rmr-share')}${actionKpi('Average adoption',pct(k.average_adoption),'Portfolio product usage','adoption')}${actionKpi('Needs attention',number(k.needs_attention),'Customer-success follow-up','attention')}${actionKpi('Expansion signals',number(k.expansion_signals),'Requests and strong interest','expansion')}${actionKpi('Onboarding',number(k.onboarding_clients),'Implementations in progress','onboarding')}</div>
  <section class="table-card"><div class="table-toolbar"><div><h2>Client portfolio</h2><div id="portfolio-filter-note" class="tiny muted">Showing all clients.</div></div><div class="grow"></div><button class="button secondary small" id="portfolio-clear-filter" hidden>Clear filter</button><input class="input" id="portfolio-search" placeholder="Search clients"></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Client</th><th>Status</th><th>Client access</th><th>Sold by</th><th>Website</th><th>${acronym('PIQ')}</th><th>${acronym('MRR')}</th><th>Adoption</th><th>Health</th><th>Action</th></tr></thead><tbody id="portfolio-body">${data.tenants.map(t => `<tr data-tenant-id="${t.id}" data-status="${esc(t.status)}" data-health="${esc(t.health_status)}" data-adoption="${t.adoption_score}" data-search="${esc(`${t.name} ${t.industry} ${t.country}`.toLowerCase())}"><td><strong>${esc(t.name)}</strong><div class="tiny muted">${esc(t.industry)} · ${esc(t.country)}</div></td><td>${badge(t.status,statusTone(t.status))}</td><td>${badge(accessLabel(t.access_state),statusTone(t.access_state))}</td><td>${esc(t.seller_org)}</td><td>${esc(websiteMode(t.website_mode))}</td><td>${t.piq_active ? badge('Active','purple') : badge('—','gray')}</td><td><strong>${money(t.mrr_cents)}</strong></td><td>${pct(t.adoption_score)}</td><td>${badge(t.health_status,statusTone(t.health_status))}</td><td><button class="button secondary small" data-client360="${t.id}">Open Client 360</button></td></tr>`).join('')}</tbody></table></div></section>`;
  $('#add-client').addEventListener('click', () => addClientModal(ctx));
  $$('[data-route]').forEach(btn => btn.addEventListener('click', () => ctx.navigate(btn.dataset.route)));
  $$('[data-client360]').forEach(btn => btn.addEventListener('click', () => ctx.navigate(`client-360?tenant=${btn.dataset.client360}`)));

  let activeFilter='all';
  const filterLabels={all:'all clients',active:'active clients',attention:'clients needing attention',onboarding:'clients currently onboarding'};
  const updateRows=()=>{
    const q=$('#portfolio-search').value.toLowerCase().trim();
    let visible=0;
    $$('#portfolio-body tr').forEach(row=>{
      const matchesSearch=!q||row.dataset.search.includes(q);
      const matchesFilter=activeFilter==='all'||
        (activeFilter==='active'&&['live','private'].includes(row.dataset.status))||
        (activeFilter==='attention'&&['Attention','At Risk'].includes(row.dataset.health))||
        (activeFilter==='onboarding'&&['onboarding','invitation_pending'].includes(row.dataset.status));
      row.hidden=!(matchesSearch&&matchesFilter);if(!row.hidden)visible++;
    });
    $('#portfolio-filter-note').textContent=`Showing ${visible} ${filterLabels[activeFilter]}${q?` matching “${q}”`:''}.`;
    $('#portfolio-clear-filter').hidden=activeFilter==='all'&&!q;
  };
  $('#portfolio-search').addEventListener('input',updateRows);
  $('#portfolio-clear-filter').addEventListener('click',()=>{activeFilter='all';$('#portfolio-search').value='';updateRows()});
  $$('[data-portfolio-kpi]').forEach(btn=>btn.addEventListener('click',()=>{
    const action=btn.dataset.portfolioKpi;
    if(['active','attention','onboarding'].includes(action)){activeFilter=action;updateRows();document.querySelector('.table-card')?.scrollIntoView({behavior:'smooth',block:'start'});return}
    if(action==='expansion'){ctx.navigate('service-requests');return}
    if(action==='adoption'){ctx.navigate('client-success');return}
    if(['recognized','rmr-share'].includes(action)){ctx.navigate('partner-economics');return}
    if(action==='mrr')portfolioRevenueDetail(data);
  }));
}

function portfolioRevenueDetail(data){
  const rows=[...data.tenants].sort((a,b)=>b.mrr_cents-a.mrr_cents);
  modal({title:'Contracted Monthly Revenue',wide:true,body:`<div class="notice-card"><strong>MRR calculation</strong><p>Contracted monthly revenue is the sum of each client’s active monthly service schedule.</p></div><div class="v531-detail-list">${rows.map(t=>`<button data-portfolio-detail-client="${t.id}"><span><strong>${esc(t.name)}</strong><small>${esc(t.status)} · ${pct(t.adoption_score)} adoption</small></span><b>${money(t.mrr_cents)}</b></button>`).join('')}</div>`,footer:'<button class="button" data-close-modal>Done</button>',onOpen:root=>$$('[data-portfolio-detail-client]',root).forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('[data-close-modal]')?.click();location.hash=`#/client-360?tenant=${btn.dataset.portfolioDetailClient}`}))});
}

async function addClientModal(ctx) {
  const catalog = (await api('/api/service-catalog')).services;
  const body = `<form id="add-client-form" class="form-grid" novalidate>
    ${field('Company name','name','text','',true)}${field('Client URL slug','slug','text','',true)}${field('Industry','industry','text','Professional Services')}${field('Country','country','text','United States')}${field('Time zone','timezone','text','America/Phoenix',true)}
    ${selectField('Originating organization','seller_org',[['RMR','RMR'],['Step2','Step2']])}${field('Originating salesperson','seller_name','text','')}
    ${selectField('Website mode','website_mode',[['managed','RMR Managed Website'],['custom','Custom Connected Website'],['external','Existing External Website']])}${field('Website URL','website_url','url','')}
    ${field('Primary contact','primary_contact_name','text','',true)}${field('Primary contact email','primary_contact_email','email','',true)}
    <label class="list-item full"><input type="checkbox" name="invite_primary_admin" checked><span class="grow"><strong>Invite primary contact as Client Administrator</strong><small class="muted">The client creates their own password through a one-time activation link.</small></span></label>
    <div class="field full"><label>Initial services</label><div class="grid two">${catalog.filter(s=>['platform_core','crm','forecasting_management','managed_website','external_website_connection','training','piq_access','piq_enhancement'].includes(s.code)).map(s=>`<label class="list-item"><input type="checkbox" name="services" value="${s.code}" ${['platform_core','crm'].includes(s.code)?'checked':''}><span class="grow"><strong>${esc(s.name)}</strong><small class="muted">Standard ${money(s.standard_price_cents)} · ${esc(s.cadence)}</small></span><input class="input" style="width:115px" type="number" min="0" step="0.01" data-service-price="${s.code}" value="${s.standard_price_cents/100}"></label>`).join('')}</div></div>
  </form>`;
  modal({title:'Add New Client',body,wide:true,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-client">Create client</button>',onOpen:(root,close)=>{
    const form=$('#add-client-form',root), nameInput=$('[name=name]',root), slugInput=$('[name=slug]',root), save=$('#save-client',root);
    nameInput.addEventListener('input',()=>{if(!slugInput.dataset.edited)slugInput.value=nameInput.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')});
    slugInput.addEventListener('input',()=>slugInput.dataset.edited='1');
    save.addEventListener('click',async()=>{
      if(!form.reportValidity())return;
      save.disabled=true; save.textContent='Creating client…';
      const fd=new FormData(form);
      const services=[...root.querySelectorAll('input[name=services]:checked')].map(box=>({service_code:box.value,contract_price_cents:Math.round(Number(root.querySelector(`[data-service-price="${box.value}"]`).value)*100),usage_price_cents:box.value==='piq_enhancement'?Math.round(Number(root.querySelector(`[data-service-price="${box.value}"]`).value)*100):0}));
      try{
        const result=await api('/api/tenants',{method:'POST',body:{name:fd.get('name'),slug:fd.get('slug'),industry:fd.get('industry'),country:fd.get('country'),timezone:fd.get('timezone'),seller_org:fd.get('seller_org'),seller_name:fd.get('seller_name'),website_mode:fd.get('website_mode'),website_url:fd.get('website_url'),primary_contact_name:fd.get('primary_contact_name'),primary_contact_email:fd.get('primary_contact_email'),invite_primary_admin:form.invite_primary_admin.checked,services}});
        close(); state.selectedTenantId=result.tenant.id; localStorage.setItem('rmr_selected_tenant',result.tenant.id); await ctx.refreshTenants({refreshShell:true});
        showClientCreated(result,ctx);
      }catch(error){applyFieldErrors(root,error.fieldErrors);toast(error.message,'error');save.disabled=false;save.textContent='Create client';}
    });
  }});
}

function showClientCreated(result,ctx){
  const invitation=result.invitation;
  modal({title:'Client created',body:`<div class="section-block"><div class="eyebrow">NEXT STEP</div><h2>${esc(result.tenant.name)}</h2><p>The client tenant, onboarding record, website configuration, and service schedule were created.</p>${invitation?`<div class="notice-card"><strong>${esc(invitation.delivery_status||invitation.invitation.delivery_status||"Client Administrator invitation created")}</strong><p>${esc(invitation.invitation.email)}</p>${invitation.activation_url?`<div class="secure-link"><code>${esc(invitation.activation_url)}</code><button class="button secondary small" id="copy-activation">Copy link</button></div>`:'<p class="muted">Delivery is pending through the configured email service. The application does not claim the email was sent until delivery is confirmed.</p>'}</div>`:'<div class="notice-card"><strong>Client access not yet provisioned</strong><p>Invite a Client Administrator from Client 360 before go-live.</p></div>'}</div>`,footer:'<button class="button secondary" id="open-client360">Open Client 360</button><button class="button" id="continue-client-onboarding">Continue onboarding</button>',onOpen:(root,close)=>{
    $('#copy-activation',root)?.addEventListener('click',()=>copyText(invitation.activation_url));
    $('#open-client360',root).addEventListener('click',()=>{close();ctx.navigate(`client-360?tenant=${result.tenant.id}`)});
    $('#continue-client-onboarding',root).addEventListener('click',()=>{close();ctx.navigate(`onboarding?tenant=${result.tenant.id}`)});
  }});
}

async function client360(page,ctx){
  const tenant=selectedTenant();
  if(!tenant){page.innerHTML=empty('Select a client','Choose a client from the selector or Portfolio Command Center.');return;}
  const [data,themeData]=await Promise.all([api(`/api/tenants/${tenant.id}/client360`),api(`/api/tenants/${tenant.id}/theme`)]);
  const t=data.tenant,m=data.metrics,f=data.financials,a=data.access,o=data.onboarding,w=data.website;
  const crumbs=breadcrumb([{label:'Portfolio',route:'portfolio'},{label:t.name}]);
  page.innerHTML=`${pageHead(`${esc(t.name)} — Client 360`,'RMR and Step2 relationship, adoption, services, access, and authorized support view.',`<button class="button secondary" data-route="portfolio">Return to Portfolio</button><button class="button secondary" id="edit-client">Edit Client Details</button><button class="button secondary" id="manage-access">Manage Client Access</button><button class="button secondary" id="manage-tenant-theme">Manage Branding</button><button class="button" id="open-client-workspace">Open Client Workspace</button>`,crumbs)}
  <section class="hero-card"><div><div class="eyebrow">CLIENT RELATIONSHIP</div><h2>${esc(t.name)}</h2><p>${esc(t.industry)} · ${esc(t.country)} · ${esc(websiteMode(t.website_mode))}</p></div><div class="hero-stat"><span>Client status</span><strong>${esc(t.status)}</strong><small>${esc(t.health_status)}</small></div></section>
  <div class="kpi-grid">${kpi(acronym('MRR'),money(f.mrr_cents),'Contracted monthly services')}${kpi('Usage revenue',money(f.usage_revenue_cents),'Current period')}${kpi('Adoption',m.adoption_state==='measured'?pct(m.adoption_score):'Not measured',m.adoption_state==='measured'?'Platform activity':'Begins after client activity')}${kpi('Training',m.training_state==='measured'?pct(m.training_completion_pct):'Not assigned',m.training_state==='measured'?'Assigned learning':'No required training assigned')}${kpi('Client access',accessLabel(a.access_state),a.active_client_admins.length?`${a.active_client_admins.length} active administrator(s)`:a.pending_invitation?'Invitation pending':'No client user')}${kpi('Onboarding',pct(o?.project?.readiness_pct||0),`${o?.completed_steps||0} of ${o?.total_steps||0} stages`)}</div>
  <div class="grid two"><section class="card"><h2>RMR relationship actions</h2><div class="action-grid"><button class="action-card" data-route="pricing"><strong>Client Pricing</strong><span>Services, rates, and billing schedule</span></button><button class="action-card" data-route="onboarding"><strong>Client Onboarding</strong><span>Setup stages and client access</span></button><button class="action-card" data-route="crm"><strong>Client Operations — Read Only</strong><span>Review CRM and activity for support</span></button><button class="action-card" data-route="website"><strong>Website Management</strong><span>Configuration and content</span></button></div></section>
  <section class="card"><h2>Website & platform</h2><div class="list-item"><span class="grow"><strong>${esc(websiteMode(w.mode||t.website_mode))}</strong><small class="muted">${w.configured?'Website is configured':'Website URL is not configured'}</small></span>${w.configured?`<button class="button secondary small" id="open-website">View website</button>`:badge('Needs setup','amber')}</div><div class="list-item"><span class="grow"><strong>Primary contact</strong><small class="muted">${esc(t.primary_contact_name||'Not set')} · ${esc(t.primary_contact_email||'')}</small></span></div>${themeSummaryCard(themeData,{buttonId:'manage-tenant-theme-card',compact:true})}</section></div>
  <div class="grid two"><section class="card"><h2>Active services</h2><div class="grid">${data.services.length?data.services.map(s=>`<div class="list-item"><span class="grow"><strong>${esc(s.catalog.name)}</strong><small class="muted">${money(s.tenant_service.contract_price_cents)} · ${esc(s.tenant_service.cadence)}</small></span>${badge(s.tenant_service.status,statusTone(s.tenant_service.status))}</div>`).join(''):empty('No services','Add services under Client Pricing.')}</div></section><section class="card"><h2>Client value evidence</h2><div class="grid two">${kpi('CRM accounts',number(m.accounts),m.accounts?'Client-owned records':'No records yet')}${kpi('Open opportunities',number(m.opportunities),m.opportunities?'Client pipeline':'No opportunities yet')}${kpi('Leads',number(m.leads),m.leads?'Client lead flow':'No leads yet')}${kpi('Forecast use',m.forecast_used?'Active':'Not started',m.forecast_used?`Accuracy ${pct(m.forecast_accuracy_pct)}`:'No forecast created')}</div><p class="tiny muted">Operational values are client-owned and read-only to RMR/Step2.</p></section></div>`;
  bindBreadcrumbs(ctx.navigate);
  $$('[data-route]').forEach(btn=>btn.addEventListener('click',()=>ctx.navigate(btn.dataset.route)));
  $('#edit-client').addEventListener('click',()=>editClientModal(t,ctx));
  $('#manage-access').addEventListener('click',()=>clientAccessModal(t,ctx));
  $('#manage-tenant-theme').addEventListener('click',()=>openThemeManager(t.id,ctx,{title:'Tenant Branding'}));
  $('#manage-tenant-theme-card')?.addEventListener('click',()=>openThemeManager(t.id,ctx,{title:'Tenant Branding'}));
  $('#open-client-workspace').addEventListener('click',()=>ctx.enterClientWorkspace(t.id));
  $('#open-website')?.addEventListener('click',()=>window.open(w.open_url,'_blank','noopener'));
}


function editClientModal(tenant,ctx){
  modal({title:`Edit Client Details — ${esc(tenant.name)}`,body:`<form id="edit-client-form" class="form-grid" novalidate>${field('Company name','name','text',tenant.name,true)}${field('Industry','industry','text',tenant.industry||'')}${field('Country','country','text',tenant.country||'')}${field('Time zone','timezone','text',tenant.timezone||'America/Phoenix',true)}${field('Primary contact','primary_contact_name','text',tenant.primary_contact_name||'')}${field('Primary contact email','primary_contact_email','email',tenant.primary_contact_email||'')}${selectField('Website mode','website_mode',[['managed','RMR Managed Website'],['custom','Custom Connected Website'],['external','Existing External Website']],tenant.website_mode)}${field('Website URL','website_url','url',tenant.website_url||'')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-client-details">Save changes</button>',wide:true,onOpen:(root,close)=>$('#save-client-details',root).addEventListener('click',async()=>{const form=$('#edit-client-form',root);if(!form.reportValidity())return;try{await api(`/api/tenants/${tenant.id}`,{method:'PATCH',body:{name:form.name.value,industry:form.industry.value,country:form.country.value,timezone:form.timezone.value,primary_contact_name:form.primary_contact_name.value,primary_contact_email:form.primary_contact_email.value,website_mode:form.website_mode.value,website_url:form.website_url.value}});close();await ctx.refreshTenants({refreshShell:true});state.selectedTenantId=tenant.id;toast('Client details updated');ctx.navigate(`client-360?tenant=${tenant.id}`)}catch(error){applyFieldErrors(root,error.fieldErrors);toast(error.message,'error')}})});
}

async function clientAccessModal(tenant,ctx){
  const data=await api(`/api/tenants/${tenant.id}/access`);
  const pending=data.access.pending_invitation;
  const env=data.delivery_environment||{};
  modal({title:`${esc(tenant.name)} — Client Access`,body:`<div class="section-block"><div class="eyebrow">ACCESS STATUS</div><h2>${esc(accessLabel(data.access.access_state))}</h2><p>${data.access.active_client_admins.length?'The client has active administrator access.':pending?'The invitation is awaiting acceptance.':'No Client Administrator has been provisioned.'}</p><div class="v531-delivery-state"><strong>${esc(env.label||'Invitation delivery')}</strong><small>${esc(env.description||'Delivery status is based on the configured environment.')}</small></div></div><div class="section-block"><h3>Active users</h3>${data.users.length?`<div class="grid">${data.users.map(u=>`<div class="list-item"><span class="grow"><strong>${esc(u.full_name)}</strong><small class="muted">${esc(u.email)} · ${esc((u.tenant_role||'').replaceAll('_',' '))}</small></span>${badge(u.active?'Active':'Inactive',u.active?'green':'gray')}</div>`).join('')}</div>`:empty('No active users','Invite the first Client Administrator.')}</div><div class="section-block"><h3>Invitations</h3>${data.invitations.length?`<div class="grid">${data.invitations.map(i=>`<div class="list-item v531-invitation-row"><span class="grow"><strong>${esc(i.full_name)}</strong><small class="muted">${esc(i.email)} · Expires ${dateFmt(i.expires_at)}</small><small class="v531-delivery-label">${esc(i.delivery_status||i.status)}</small></span>${badge(i.status,statusTone(i.status))}${i.status==='pending'?`<button class="button secondary small" data-resend="${i.id}">${i.delivery_mode==='local_link'?'Reissue Link':'Resend / Reissue'}</button>`:''}</div>`).join('')}</div>`:empty('No invitations','Create the first client access invitation.')}</div>`,footer:'<button class="button secondary" data-close-modal>Close</button><button class="button" id="invite-user">+ Invite Client User</button>',wide:true,onOpen:(root,close)=>{
    $('#invite-user',root).addEventListener('click',()=>{close();inviteUserModal(tenant,ctx)});
    $$('[data-resend]',root).forEach(btn=>btn.addEventListener('click',async()=>{try{const result=await api(`/api/invitations/${btn.dataset.resend}/resend`,{method:'POST',body:{}});close();showActivationLink(result,tenant.name)}catch(e){toast(e.message,'error')}}));
  }});
}

function inviteUserModal(tenant,ctx){
  const roles=[['CLIENT_ADMIN','Client Administrator'],['VP_SALES','VP of Sales'],['SALES_MANAGER','Sales Manager'],['SALES_REP','Sales Representative'],['MARKETING_USER','Marketing User'],['EXECUTIVE_VIEWER','Executive Viewer']];
  modal({title:`Invite user — ${esc(tenant.name)}`,body:`<form id="invite-form" class="form-grid">${field('Full name','full_name','text',tenant.primary_contact_name||'',true)}${field('Email','email','email',tenant.primary_contact_email||'',true)}${selectField('Role','tenant_role',roles,'CLIENT_ADMIN')}${field('Team or region','team_name','text','Administration')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="send-invite">Create invitation</button>',onOpen:(root,close)=>$('#send-invite',root).addEventListener('click',async()=>{const form=$('#invite-form',root);if(!form.reportValidity())return;try{const result=await api(`/api/tenants/${tenant.id}/invitations`,{method:'POST',body:{full_name:form.full_name.value,email:form.email.value,tenant_role:form.tenant_role.value,team_name:form.team_name.value}});close();showActivationLink(result,tenant.name)}catch(e){applyFieldErrors(root,e.fieldErrors);toast(e.message,'error')}})});
}

function showActivationLink(result,tenantName){
  const status=result.delivery_status||result.invitation?.delivery_status||'Invitation created';
  modal({title:'Client invitation created',body:`<div class="v531-delivery-state"><strong>${esc(status)}</strong><small>${result.activation_url?'This local Product Owner environment did not send email. Copy or open the secure activation link below.':'Delivery depends on the configured production email provider. No delivery is claimed until the provider confirms it.'}</small></div><p>${esc(result.invitation.full_name)} can activate access to ${esc(tenantName)}.</p>${result.activation_url?`<div class="secure-link"><code>${esc(result.activation_url)}</code><button class="button secondary small" id="copy-link">Copy link</button><button class="button secondary small" id="open-link">Open</button></div>`:'<p class="notice-card">The invitation is ready for the configured delivery workflow.</p>'}`,footer:'<button class="button" data-close-modal>Done</button>',onOpen:root=>{if(result.activation_url){$('#copy-link',root).addEventListener('click',()=>copyText(result.activation_url));$('#open-link',root).addEventListener('click',()=>window.open(result.activation_url,'_blank','noopener'))}}});
}

async function clientSuccess(page,ctx){
  const summary=await api('/api/portfolio/summary');
  const rows=await Promise.all(summary.tenants.map(async tenant=>({tenant,...(await api(`/api/tenants/${tenant.id}/success`))})));
  const actionCount=rows.reduce((sum,row)=>sum+row.actions.length,0);
  page.innerHTML=`${pageHead('Client Success Intelligence','Use adoption, training, workflow activity, and value evidence to decide where action is needed.')}<div class="kpi-grid">${actionKpi('Average adoption',pct(summary.kpis.average_adoption),'Across all clients','adoption','success')}${actionKpi('Needs attention',number(summary.kpis.needs_attention),'Follow-up recommended','attention','success')}${actionKpi('Expansion signals',number(summary.kpis.expansion_signals),'Requests and repeated exploration','expansion','success')}${actionKpi('Active clients',number(summary.kpis.active_clients),'Current portfolio','active','success')}</div><section class="table-card"><div class="table-toolbar"><div><h2>Client value scorecard</h2><div id="success-filter-note" class="tiny muted">Showing all clients.</div></div><div class="grow"></div><button class="button secondary small" id="success-clear-filter" hidden>Clear filter</button></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Client</th><th>Adoption</th><th>Active users</th><th>Training</th><th>Forecast</th><th>Accounts</th><th>Opportunities</th><th>Leads</th><th>Health</th><th></th></tr></thead><tbody id="success-body">${rows.map(r=>`<tr data-success-client="${r.tenant.id}" data-health="${esc(r.metrics.health_status)}" data-adoption="${r.metrics.adoption_score}" data-has-expansion="${r.actions.some(a=>a.type==='Expansion')}"><td><strong>${esc(r.tenant.name)}</strong></td><td>${pct(r.metrics.adoption_score)}</td><td>${number(r.metrics.active_users)}</td><td>${pct(r.metrics.training_completion_pct)}</td><td>${r.metrics.forecast_used?badge('Active','green'):badge('Not started','amber')}</td><td>${number(r.metrics.accounts)}</td><td>${number(r.metrics.opportunities)}</td><td>${number(r.metrics.leads)}</td><td>${badge(r.metrics.health_status,statusTone(r.metrics.health_status))}</td><td><button class="button secondary small" data-client360="${r.tenant.id}">Client 360</button></td></tr>`).join('')}</tbody></table></div></section><section class="grid two" id="success-actions">${rows.flatMap(r=>r.actions.map(a=>`<div class="card v531-success-action" data-action-type="${esc(a.type)}" data-action-client="${r.tenant.id}"><div class="eyebrow">${esc(a.type)}</div><h3>${esc(r.tenant.name)} — ${esc(a.title)}</h3><p>${esc(a.action)}</p><button class="button secondary small" data-success-client360="${r.tenant.id}">Review Client →</button></div>`)).join('')||empty('No active recommendations','Current portfolio data does not identify a coaching, adoption, retention, or expansion action.')}</section>`;
  $$('[data-client360],[data-success-client360]').forEach(btn=>btn.addEventListener('click',()=>ctx.navigate(`client-360?tenant=${btn.dataset.client360||btn.dataset.successClient360}`)));
  let filter='all';
  const update=()=>{
    let visible=0;
    $$('#success-body tr').forEach(row=>{const show=filter==='all'||filter==='active'||(filter==='attention'&&!['Healthy','Onboarding'].includes(row.dataset.health))||(filter==='expansion'&&row.dataset.hasExpansion==='true');row.hidden=!show;if(show)visible++});
    $$('#success-actions .v531-success-action').forEach(card=>card.hidden=filter==='expansion'&&card.dataset.actionType!=='Expansion');
    $('#success-filter-note').textContent=filter==='all'||filter==='active'?`Showing ${visible} active portfolio clients.`:filter==='attention'?`Showing ${visible} client(s) requiring attention.`:`Showing ${visible} client(s) with expansion signals.`;
    $('#success-clear-filter').hidden=filter==='all';
  };
  $('#success-clear-filter').addEventListener('click',()=>{filter='all';update()});
  $$('[data-success-kpi]').forEach(btn=>btn.addEventListener('click',()=>{const action=btn.dataset.successKpi;if(action==='adoption'){clientSuccessAdoptionDetail(rows);return}filter=action;update();document.querySelector('.table-card')?.scrollIntoView({behavior:'smooth',block:'start'})}));
}

function clientSuccessAdoptionDetail(rows){
  modal({title:'Portfolio Adoption Detail',wide:true,body:`<div class="v531-detail-list">${[...rows].sort((a,b)=>a.metrics.adoption_score-b.metrics.adoption_score).map(r=>`<button data-success-detail="${r.tenant.id}"><span><strong>${esc(r.tenant.name)}</strong><small>${esc(r.metrics.health_status)} · ${number(r.metrics.active_users)} active user(s)</small></span><b>${pct(r.metrics.adoption_score)}</b></button>`).join('')}</div>`,footer:'<button class="button" data-close-modal>Done</button>'});
}

async function pricing(page,ctx){
  const summary=await api('/api/portfolio/summary');
  const tenant=selectedTenant()||summary.tenants[0];
  if(tenant&&!state.selectedTenantId)state.selectedTenantId=tenant.id;
  const services=tenant?(await api(`/api/tenants/${tenant.id}/services`)).services:[];
  page.innerHTML=`${pageHead('Client Pricing','Configure what each client pays for its authorized services.',tenant?'<button class="button" id="add-service">+ Add service</button>':'')}<section class="table-card"><div class="table-toolbar"><h2>Clients</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Client</th><th>${acronym('MRR')}</th><th>Status</th><th></th></tr></thead><tbody>${summary.tenants.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td>${money(t.mrr_cents)}</td><td>${badge(t.status,statusTone(t.status))}</td><td><button class="button secondary small" data-price-client="${t.id}">Manage</button></td></tr>`).join('')}</tbody></table></div></section>${tenant?`<section class="table-card"><div class="table-toolbar"><h2>${esc(tenant.name)} service schedule</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Service</th><th>Standard price</th><th>Client price</th><th>Cadence</th><th>Status</th></tr></thead><tbody>${services.map(s=>`<tr><td><strong>${esc(s.catalog.name)}</strong></td><td>${money(s.catalog.standard_price_cents)}</td><td>${money(s.tenant_service.contract_price_cents)}</td><td>${esc(s.tenant_service.cadence)}</td><td>${badge(s.tenant_service.status,statusTone(s.tenant_service.status))}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;
  $$('[data-price-client]').forEach(btn=>btn.addEventListener('click',()=>{state.selectedTenantId=btn.dataset.priceClient;localStorage.setItem('rmr_selected_tenant',state.selectedTenantId);pricing(page,ctx)}));
  $('#add-service')?.addEventListener('click',()=>addServiceModal(tenant,ctx));
}

async function addServiceModal(tenant,ctx){
  const [catalog,current]=await Promise.all([api('/api/service-catalog'),api(`/api/tenants/${tenant.id}/services`)]);const existing=new Set(current.services.map(s=>s.tenant_service.service_code));const options=catalog.services.filter(s=>!existing.has(s.code));
  if(!options.length){toast('All approved services are already on this client schedule');return;}
  modal({title:`Add service — ${esc(tenant.name)}`,body:`<form id="service-form" class="form-grid">${selectField('Service','service_code',options.map(s=>[s.code,s.name]))}${field('Client contract price','contract_price','number',options[0].standard_price_cents/100,true)}${field('Usage price','usage_price','number',0)}<div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-service">Add service</button>',onOpen:(root,close)=>{const select=$('[name=service_code]',root);select.addEventListener('change',()=>{$('[name=contract_price]',root).value=(options.find(s=>s.code===select.value)?.standard_price_cents||0)/100});$('#save-service',root).addEventListener('click',async()=>{const form=$('#service-form',root);try{await api(`/api/tenants/${tenant.id}/services`,{method:'POST',body:{service_code:form.service_code.value,contract_price_cents:Math.round(Number(form.contract_price.value)*100),usage_price_cents:Math.round(Number(form.usage_price.value)*100),notes:form.notes.value}});toast('Service added');close();ctx.navigate('pricing')}catch(e){toast(e.message,'error')}})}});
}

async function partnerEconomics(page,ctx){
  const [data,categories,summary]=await Promise.all([api('/api/partner-economics'),api('/api/cost-categories'),api('/api/portfolio/summary')]);const s=data.summary;
  page.innerHTML=`${pageHead('Partner Economics','Revenue, known costs, allocation policy, and RMR/Step2 transaction evidence.',`<button class="button secondary" id="add-rule">Allocation rule</button><button class="button" id="add-cost">+ Add cost</button>`)}<div class="notice-card"><strong>Accounting policy remains RMR-controlled.</strong><p>${esc(data.policy_status.warning)}</p></div><div class="kpi-grid">${kpi('Revenue',money(s.revenue_cents),'Recognized transactions')}${kpi('Transaction direct costs',money(s.transaction_direct_costs_cents),'Service-level costs')}${kpi('Additional direct costs',money(s.additional_direct_costs_cents),'Entered client/service costs')}${kpi('Allocated shared costs',money(s.allocated_shared_operating_costs_cents),'Only approved rules')}${kpi('Policy pending costs',money(s.unallocated_policy_pending_cents),'Excluded until approved')}${kpi('Contribution',money(s.contribution_after_allocated_costs_cents),'After known allocated costs')}${kpi('RMR share',money(s.rmr_share_cents),'Existing split rules')}${kpi('Step2 share',money(s.step2_share_cents),'Existing split rules')}</div><div class="grid two"><section class="table-card"><div class="table-toolbar"><h2>Cost entries</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Category</th><th>Scope</th><th>Amount</th><th>Basis</th><th>Policy</th></tr></thead><tbody>${data.cost_model.entries.length?data.cost_model.entries.map(x=>`<tr><td>${esc(x.category?.name||x.entry.category_code)}</td><td>${esc(x.entry.allocation_scope)}</td><td>${money(x.entry.amount_cents)}</td><td>${esc(x.allocation_basis_used)}</td><td>${x.policy_pending?badge('Policy pending','amber'):badge('Allocated','green')}</td></tr>`).join(''):`<tr><td colspan="5">${empty('No operating costs entered','Add hosting, software/API, payment processing, staff, support, or other costs.')}</td></tr>`}</tbody></table></div></section><section class="table-card"><div class="table-toolbar"><h2>Revenue by service</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Service</th><th>Revenue</th><th>Direct cost</th><th>RMR</th><th>Step2</th></tr></thead><tbody>${data.by_service.map(x=>`<tr><td>${esc(x.service_name)}</td><td>${money(x.revenue_cents)}</td><td>${money(x.direct_costs_cents)}</td><td>${money(x.rmr_share_cents)}</td><td>${money(x.step2_share_cents)}</td></tr>`).join('')}</tbody></table></div></section></div>`;
  $('#add-cost').addEventListener('click',()=>costModal(categories.categories,summary.tenants,ctx));
  $('#add-rule').addEventListener('click',()=>allocationRuleModal(categories.categories,ctx));
}

function costModal(categories,tenants,ctx){modal({title:'Add operating cost',body:`<form id="cost-form" class="form-grid">${field('Period','period','month',new Date().toISOString().slice(0,7),true)}${selectField('Cost category','category_code',categories.map(c=>[c.code,c.name]))}${selectField('Allocation scope','allocation_scope',[['direct_tenant_service','Direct client/service'],['tenant','Client-level'],['portfolio','Shared portfolio cost']])}${selectField('Client','tenant_id',[['','No specific client'],...tenants.map(t=>[t.id,t.name])])}${field('Service code (optional)','service_code','text','')}${field('Amount','amount','number',0,true)}${selectField('Allocation basis','allocation_basis',[['direct','Direct'],['equal_client','Equal by client'],['revenue_share','Revenue share'],['pending_policy','Policy pending']],'pending_policy')}<div class="field full"><label>Description</label><textarea name="description"></textarea></div></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-cost">Save cost</button>',onOpen:(root,close)=>$('#save-cost',root).addEventListener('click',async()=>{const f=$('#cost-form',root);try{await api('/api/partner-economics/costs',{method:'POST',body:{period:f.period.value,category_code:f.category_code.value,tenant_id:f.tenant_id.value||null,service_code:f.service_code.value||null,amount_cents:Math.round(Number(f.amount.value)*100),allocation_scope:f.allocation_scope.value,allocation_basis:f.allocation_basis.value,partner_settlement_treatment:'pending_policy',description:f.description.value}});toast('Cost recorded');close();ctx.navigate('partner-economics')}catch(e){toast(e.message,'error')}})});}
function allocationRuleModal(categories,ctx){modal({title:'Add effective-dated cost allocation rule',body:`<form id="rule-form" class="form-grid">${selectField('Cost category','category_code',categories.map(c=>[c.code,c.name]))}${selectField('Allocation basis','allocation_basis',[['equal_client','Equal by client'],['revenue_share','Revenue share'],['manual','Manual'],['pending_policy','Policy pending']])}${selectField('Partner settlement treatment','partner_settlement_treatment',[['pending_policy','Policy pending'],['before_split','Deduct before split'],['rmr_cost','RMR cost'],['step2_cost','Step2 cost'],['shared_cost','Shared cost']])}${field('Effective date','effective_date','date',new Date().toISOString().slice(0,10),true)}<div class="field full"><label>Policy note</label><textarea name="notes"></textarea></div></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-rule">Save rule</button>',onOpen:(root,close)=>$('#save-rule',root).addEventListener('click',async()=>{const f=$('#rule-form',root);try{await api('/api/partner-economics/allocation-rules',{method:'POST',body:{category_code:f.category_code.value,allocation_basis:f.allocation_basis.value,partner_settlement_treatment:f.partner_settlement_treatment.value,effective_date:f.effective_date.value,notes:f.notes.value}});toast('Allocation rule saved');close();ctx.navigate('partner-economics')}catch(e){toast(e.message,'error')}})});}

async function onboarding(page,ctx,autoOpen=true){
  const data=await api('/api/onboarding');
  const requested=state.routeQuery.tenant;
  page.innerHTML=`${pageHead('Client Onboarding','Complete the guided setup, provision client access, and validate go-live readiness.',`<button class="button" id="add-client-onboarding">+ Add New Client</button>`)}<div class="kpi-grid">${kpi('Active implementations',number(data.projects.filter(x=>x.project.status!=='complete').length),'Currently onboarding')}${kpi('Average readiness',pct(data.projects.reduce((a,x)=>a+x.project.readiness_pct,0)/Math.max(data.projects.length,1)),'Across implementations')}${kpi('Awaiting client access',number(data.projects.filter(x=>x.access.access_state!=='active').length),'Invitation or activation required')}${kpi('Completed',number(data.projects.filter(x=>x.project.status==='complete').length),'Ready and live')}</div><div class="grid three">${data.projects.map(item=>`<section class="card"><div style="display:flex;justify-content:space-between"><div><h3>${esc(item.tenant.name)}</h3><p class="muted">Stage ${item.project.current_stage} of ${item.steps.length}</p></div>${badge(item.project.status,statusTone(item.project.status))}</div><div class="progress-bar"><span style="width:${item.project.readiness_pct}%"></span></div><div style="display:flex;justify-content:space-between;margin:12px 0"><strong>${item.project.readiness_pct}%</strong><span class="tiny muted">${esc(accessLabel(item.access.access_state))}</span></div><button class="button ${item.project.status==='complete'?'secondary':''}" data-onboard="${item.tenant.id}">${item.project.status==='complete'?'Review onboarding':'Continue setup'}</button></section>`).join('')}</div>`;
  $('#add-client-onboarding').addEventListener('click',()=>addClientModal(ctx));
  $$('[data-onboard]').forEach(btn=>btn.addEventListener('click',()=>onboardingModal(btn.dataset.onboard,ctx)));
  if(requested && autoOpen){const item=data.projects.find(x=>x.tenant.id===requested);if(item)setTimeout(()=>onboardingModal(item.tenant.id,ctx),0)}
}

async function onboardingModal(tenantId,ctx){
  let item=await api(`/api/tenants/${tenantId}/onboarding`);let index=Math.max(0,item.steps.findIndex(s=>s.stage_number===item.project.current_stage));
  const render=(root)=>{const step=item.steps[index];const isFinal=step.stage_number===item.steps.length;const requirement=step.requirement||{status:'ready',summary:'',missing:[]};const waiting=isFinal&&item.completion.waiting_for_client_admin_activation;root.querySelector('.modal-body').innerHTML=`<div class="stepper">${item.steps.map((s,i)=>`<button class="step-button ${s.status==='complete'?'complete':''} ${i===index?'current':''}" data-step-index="${i}"><span class="step-number">${s.status==='complete'?'✓':s.stage_number}</span><strong>${esc(s.name)}</strong><small>${esc(s.status.replaceAll('_',' '))}</small></button>`).join('')}</div><div class="grid two"><section><div class="eyebrow">STAGE ${step.stage_number}</div><h2>${esc(step.name)}</h2><p class="muted">Responsible: ${esc(step.owner_role)}</p><div class="v531-requirement ${requirement.status}"><strong>${requirement.status==='blocked'?'Required setup is incomplete':requirement.status==='optional'?'Optional stage':'Required setup evidence is ready'}</strong><p>${esc(requirement.summary||'')}</p>${(requirement.missing||[]).length?`<ul>${requirement.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div><div class="field"><label>Setup details</label><textarea name="details">${esc(step.data_json?.details||'')}</textarea></div><div class="field"><label>Implementation notes <small>(optional)</small></label><textarea name="notes">${esc(step.notes||'')}</textarea></div></section><section><div class="card"><h3>Client access</h3><p>${item.access.active_client_admins.length?'Client Administrator is active.':item.access.pending_invitation?'Invitation is awaiting acceptance.':'No Client Administrator invitation exists.'}</p>${item.access.active_client_admins.map(u=>`<div class="list-item"><span class="grow"><strong>${esc(u.full_name)}</strong><small>${esc(u.email)}</small></span>${badge('Active','green')}</div>`).join('')}${item.access.pending_invitation?`<div class="list-item"><span class="grow"><strong>${esc(item.access.pending_invitation.full_name)}</strong><small>${esc(item.access.pending_invitation.email)}</small></span>${badge('Pending','amber')}</div>`:''}<div class="v531-access-actions"><button class="button secondary" id="onboarding-access">Manage access</button>${item.access.pending_invitation?'<button class="button secondary" id="onboarding-reissue">Reissue activation link</button>':''}</div></div>${isFinal?`<div class="notice-card ${waiting?'v531-waiting':''}"><strong>${waiting?'Waiting for Client Administrator Activation':'Go-live gate'}</strong><p>${item.completion.ready_for_go_live?'Earlier stages and client access are ready. Complete this stage to activate the client.':waiting?'The client must accept the invitation before RMR can complete go-live. Use Reissue activation link if a fresh secure link is needed.':'Complete earlier stages and activate a Client Administrator before go-live.'}</p></div>`:''}</section></div>`;
    root.querySelector('.modal-foot').innerHTML=`<button class="button secondary" id="previous-step" ${index===0?'disabled':''}>Previous</button><button class="button secondary" id="save-step">Save progress</button><button class="button" id="complete-step" ${requirement.status==='blocked'?'disabled':''}>${isFinal?'Complete go-live':'Complete & continue'}</button><button class="button secondary" id="next-step" ${index===item.steps.length-1?'disabled':''}>Next</button>`;
    $$('[data-step-index]',root).forEach(btn=>btn.addEventListener('click',()=>{index=Number(btn.dataset.stepIndex);render(root)}));
    $('#previous-step',root).addEventListener('click',()=>{if(index>0){index--;render(root)}});$('#next-step',root).addEventListener('click',()=>{if(index<item.steps.length-1){index++;render(root)}});
    $('#onboarding-access',root).addEventListener('click',()=>clientAccessModal(item.tenant,ctx));
    $('#onboarding-reissue',root)?.addEventListener('click',async()=>{try{const result=await api(`/api/invitations/${item.access.pending_invitation.id}/resend`,{method:'POST',body:{}});showActivationLink(result,item.tenant.name);item=await api(`/api/tenants/${tenantId}/onboarding`);render(root)}catch(e){toast(e.message,'error')}});
    $('#save-step',root).addEventListener('click',async()=>{try{item=await api(`/api/onboarding/steps/${step.id}`,{method:'PATCH',body:{data:{...step.data_json,details:$('[name=details]',root).value},notes:$('[name=notes]',root).value,status:step.status==='not_started'?'in_progress':step.status}});index=item.steps.findIndex(s=>s.id===step.id);await onboarding($('#page'),ctx,false);toast('Progress saved');render(root)}catch(e){toast(e.message,'error')}});
    $('#complete-step',root).addEventListener('click',async()=>{try{item=await api(`/api/onboarding/steps/${step.id}`,{method:'PATCH',body:{data:{...step.data_json,details:$('[name=details]',root).value},notes:$('[name=notes]',root).value,status:'complete'}});await onboarding($('#page'),ctx,false);if(item.project.status==='complete'){root.querySelector('.modal-body').innerHTML=`<div class="completion-state"><div class="completion-icon">✓</div><h2>${esc(item.tenant.name)} is live</h2><p>Onboarding, client access, and go-live validation are complete.</p></div>`;root.querySelector('.modal-foot').innerHTML='<button class="button secondary" id="finish-onboarding">Return to Onboarding</button><button class="button secondary" id="finish-portfolio">Return to Portfolio</button><button class="button" id="finish-client360">Open Client 360</button>';$('#finish-onboarding',root).addEventListener('click',()=>{root.innerHTML='';ctx.navigate('onboarding')});$('#finish-portfolio',root).addEventListener('click',()=>{root.innerHTML='';ctx.navigate('portfolio')});$('#finish-client360',root).addEventListener('click',()=>{root.innerHTML='';ctx.navigate(`client-360?tenant=${tenantId}`)});return;}index=Math.min(index+1,item.steps.length-1);toast('Stage completed');render(root)}catch(e){const missing=e.data?.missing?.length?` Missing: ${e.data.missing.join(', ')}.`:'';toast(`${e.message}${missing}`,'error');item=await api(`/api/tenants/${tenantId}/onboarding`);index=item.steps.findIndex(s=>s.id===step.id);render(root)}});
  };
  modal({title:`${esc(item.tenant.name)} — onboarding`,body:'',wide:true,footer:'',onOpen:(root)=>render(root)});
}

